<?php
require_once 'config.php';require_once 'includes/auth_services.php';
if(isset($_SESSION['user_id'])){header('Location: '.$base_url);exit;}$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_guard();$email=mb_strtolower(trim($_POST['email']??''));if(!filter_var($email,FILTER_VALIDATE_EMAIL)){$error='Email không hợp lệ.';}else{$stmt=$conn->prepare('SELECT id,fullname,email FROM users WHERE email=? LIMIT 1');$stmt->bind_param('s',$email);$stmt->execute();$user=$stmt->get_result()->fetch_assoc();$stmt->close();if($user){$otp=(string)random_int(100000,999999);$stmt=$conn->prepare('UPDATE password_resets SET used_at=NOW() WHERE user_id=? AND used_at IS NULL');$stmt->bind_param('i',$user['id']);$stmt->execute();$stmt->close();$hash=password_hash($otp,PASSWORD_DEFAULT);$expires=date('Y-m-d H:i:s',time()+900);$stmt=$conn->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,?)');$stmt->bind_param('iss',$user['id'],$hash,$expires);$stmt->execute();$stmt->close();if(!auth_send_reset_otp($conn,$user,$otp)){$error='Không gửi được email OTP. Hãy kiểm tra cấu hình SMTP trong quản trị.';}}if($error===''){$_SESSION['reset_email']=$email;header('Location: '.$base_url.'xac-thuc-otp');exit;}}}
include 'header.php';
